import {state,DEMO} from '../../core/state.js?v=df6196a711f0';
import {api,projectQuery,exportFile} from '../../core/api.js?v=df6196a711f0';
import {refresh,repaint} from '../../core/events.js?v=df6196a711f0';
import {T,esc,icon,heading,panel,btn,badge,empty,field,select,textarea,formEnd,modal,closeModal,toast,pct,nativeRequired} from '../../core/ui.js?v=df6196a711f0';
let first=null,remaining=0,task=null,started=Date.now(),metrics=null,metricsRun='';
export async function load(){const q=await api('studio/research-queue'+projectQuery()).catch(e=>({comment:null,remaining:0,error:e.message}));first=q.comment;remaining=q.remaining;started=Date.now();metrics=await api('human-metrics'+projectQuery()+(metricsRun?'&run='+metricsRun:'')).catch(()=>null);}
export function render(){const s=state.workspace;return heading(T('Thực nghiệm kiểm tra bổ sung','Supplementary review experiment'),T('Tách riêng lượt đầu có AI, lượt kiểm tra mù và phân xử; đo hiệu quả theo ngân sách thời gian.','Separate AI-assisted first pass, blind review and adjudication; measure outcomes under a time budget.'),s.project.can_manage?btn(T('Tạo phiên kiểm tra','Create review run'),'research:create','primary','plus'):'')+`<div class="info-banner">${icon('info',18)}<span>${T('Luồng này dùng bộ nhãn nhị phân TOXIC/NON_TOXIC để nghiên cứu nhóm A/B/C/D. Gán nhãn nhiều lớp và spans ở Không gian gán nhãn. Thời gian thực tế được máy chủ ghi nhận; độ đồng thuận không thay thế tham chiếu chuyên gia.','This research workflow uses binary TOXIC/NON_TOXIC groups A/B/C/D. Use Annotation for custom classes and spans. Server timestamps measure time; agreement is not expert ground truth.')}</span></div><div class="split-grid mt16"><div class="stack">${panel(T('Lượt đầu có gợi ý AI','AI-assisted first pass'),task?`<p class="form-hint">${T('Hoàn thành lượt mù đang nhận trước.','Finish your claimed blind review first.')}</p>`:first?`<div class="between"><span class="count-pill">#${first.id}</span><span>${remaining} ${T('mẫu còn lại','remaining')}</span></div><p class="research-text">${esc(first.text)}</p><div class="ai-suggestion"><span>${T('Gợi ý AI','AI suggestion')}</span>${badge(first.ai_label)}</div><form data-submit="research:first">${select('label',T('Quyết định của bạn','Your decision'),[['NON_TOXIC',T('Không độc hại','Non-toxic')],['TOXIC',T('Độc hại','Toxic')]],first.ai_label)}${textarea('note',T('Ghi chú','Note'))}<button class="btn primary" type="submit">${T('Chốt lượt đầu','Freeze first pass')}</button></form>`:empty(T('Chưa có mẫu lượt đầu','No first-pass records'),T('Chạy model trước ở Model & API. Mẫu đã chốt lượt đầu không được viết đè.','Run a model first in Models & API. Frozen first-pass decisions cannot be overwritten.')))}${panel(T('Kiểm tra mù đang nhận','Claimed blind review'),task?`<p class="research-text">${esc(task.text)}</p><p class="form-hint">${T('Gợi ý AI, nhãn lượt đầu và nhóm mẫu đều được ẩn.','AI suggestions, first labels and research groups are hidden.')}</p><form data-submit="research:review">${select('label',T('Nhãn độc lập','Independent label'),[['NON_TOXIC',T('Không độc hại','Non-toxic')],['TOXIC',T('Độc hại','Toxic')]],'NON_TOXIC')}${textarea('note',T('Ghi chú','Note'))}<button class="btn primary" type="submit">${T('Nộp lượt kiểm tra','Submit review')}</button></form>`:empty(T('Chọn một phiên bên phải','Select a run'),T('Người kiểm tra phải khác người gán lượt đầu. Đổi TV2/TV3 trong Tài khoản khi thử demo.','The reviewer must differ from the first annotator. Switch to TV2/TV3 in Account when exploring the demo.')))}</div><div class="stack">${panel(T('Phiên kiểm tra theo ngân sách','Budgeted review runs'),s.runs.length?s.runs.map(r=>`<div class="review-run"><div class="between"><b>#${r.id} · ${esc(r.policy)}</b><span class="badge blue">${esc(r.state)}</span></div><p>${Math.round(r.used_seconds||0)} / ${r.budget_seconds}s · ${r.completed||0} ${T('đã xong','complete')} · ${r.conflicts||0} ${T('bất đồng','conflicts')}</p><div class="progress"><span style="width:${Math.min(100,100*(r.used_seconds||0)/r.budget_seconds)}%"></span></div><div class="group-grid">${Object.entries(r.stats||{}).map(([g,v])=>`<div><b>${g}</b><span>${v.n||0} · Δ${v.changed||0}</span></div>`).join('')}</div>${btn(T('Nhận mẫu kiểm tra mù','Claim a blind review'),'research:claim','sm','play',`data-id="${r.id}" ${r.state==='active'?'':'disabled'}`)}</div>`).join(''):empty(T('Chưa tạo phiên','No review runs'),T('Chốt một số mẫu lượt đầu rồi tạo phiên.','Freeze first-pass records, then create a run.')))}${panel(T('Phân xử bởi người thứ ba','Third-person adjudication'),s.conflicts?.length?s.conflicts.map(t=>`<div class="conflict-row"><p>${esc(t.text)}</p>${btn(T('Mở phân xử','Open adjudication'),'research:adjudicate','sm','',`data-id="${t.id}"`)}</div>`).join(''):`<p class="form-hint">${T('Chưa có bất đồng phù hợp với vai trò của bạn.','No eligible conflicts for your role.')}</p>`)}${panel(T('Tham chiếu & độ đúng','References & correctness'),`<div class="form-row"><label>${T('Phiên chấm trước/sau','Before/after evaluation run')}</label><select name="metrics_run"><option value="">${T('Chỉ lượt đầu','First pass only')}</option>${s.runs.map(r=>`<option value="${r.id}" ${String(r.id)===metricsRun?'selected':''}>#${r.id} · ${esc(r.policy)}</option>`).join('')}</select></div><p class="form-hint">${esc(metrics?.message||T('Nhập tham chiếu độc lập để tính chỉ số trước/sau kiểm tra. Không dùng nhãn do hệ thống vừa tạo làm ground truth.','Import independent reference labels to evaluate before/after review. Do not use the system’s own labels as ground truth.'))}</p>${metrics?.available?`<pre class="json-preview">${esc(JSON.stringify(metrics,null,2))}</pre>`:''}${s.project.can_manage?`<form data-submit="research:export">${select('run',T('Lớp kết quả nghiên cứu','Research result layer'),[['',T('Lượt đầu','First pass')],...s.runs.map(r=>[r.id,'#'+r.id+' '+r.policy])],metricsRun)}${select('format',T('Định dạng','Format'),[['csv','CSV'],['jsonl','JSONL']],'csv')}<button class="btn" type="submit">${T('Xuất kết quả nghiên cứu','Export research results')}</button></form>`:''}${s.project.can_manage?btn(T('Nhập tham chiếu CSV','Import reference CSV'),'research:references','','upload'):''}`)}</div></div>`;}
export async function action(name,el){if(name==='create'){modal(T('Tạo phiên kiểm tra','Create review run'),`<form data-submit="research:create">${select('policy',T('Chính sách chọn mẫu','Sampling policy'),[['random','Random'],['fixed','Fixed C/D'],['fixed_explore','Fixed + exploration'],['adaptive','Adaptive gain/time']],'adaptive')}${field('minutes',T('Ngân sách phút','Budget in minutes'),30,'number','min="1" max="600" required')}${field('seed','Seed',42,'number','required')}${formEnd()}</form>`);return;}if(name==='claim'){const r=await api(`runs/${el.dataset.id}/claim`,{});task=r.task;if(!task){toast(T('Không còn mẫu phù hợp.','No eligible samples.'));return;}first=null;await repaint();return;}if(name==='adjudicate'){const r=await api(`tasks/${el.dataset.id}/adjudicate`,{action:'open'});modal(T('Phân xử lượt nghiên cứu','Research adjudication'),`<p class="research-text">${esc(r.task.text)}</p><p>Lượt đầu: ${esc(r.task.first_label)} · Kiểm tra: ${esc(r.task.blind_label)}</p><form data-submit="research:adjudicate" data-id="${el.dataset.id}">${select('label',T('Nhãn chốt','Final label'),[['NON_TOXIC','NON_TOXIC'],['TOXIC','TOXIC']],'NON_TOXIC')}${textarea('note',T('Lý do bắt buộc','Required reason'),'','required')}${formEnd()}</form>`);return;}if(name==='references')modal(T('Nhập tham chiếu độc lập','Import independent references'),`<form data-submit="research:references">${field('file','CSV: id,label','','file','accept=".csv" required')}${field('name',T('Tên nguồn tham chiếu','Reference source'),'','text','required')}${formEnd()}</form>`);}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f)),project=state.workspace.project.id;if(name==='export'){await exportFile('export'+projectQuery()+(v.run?'&run='+v.run:'')+'&format='+v.format,'annotaflow-review.'+v.format);return;}if(name==='first')await api(`comments/${first.id}/first`,{...v,project,revision:first.revision,seconds:(Date.now()-started)/1000});if(name==='create')await api('runs',{...v,project});if(name==='review'){await api(`tasks/${task.id}/submit`,v);task=null;}if(name==='adjudicate')await api(`tasks/${f.dataset.id}/adjudicate`,v);if(name==='references'){if(DEMO){nativeRequired();return;}const fd=new FormData(f);fd.set('project',project);await api('references',fd);}closeModal();await refresh();toast(T('Đã lưu quyết định.','Decision saved.'));}

export async function change(e){if(e.target.name!=='metrics_run')return;metricsRun=e.target.value;metrics=await api('human-metrics'+projectQuery()+(metricsRun?'&run='+metricsRun:''));await repaint();}
